<script setup lang="ts">
const { t } = useLanguage()
import { Plus, Printer, Pencil, BookOpen } from 'lucide-vue-next'
const props=defineProps<{kind:'book'|'chapter'}>()
const db=useSupabase(), book=props.kind==='book', title=computed(()=>t(book?'financialUi.materials.books':'financialUi.materials.chapters'))
const reportSubtitle=computed(()=>t('financialUi.materials.reportSubtitle',{month:month.value||t('financialUi.materials.allMonths'),className:classes.value.find(c=>c.id===classId.value)?.title||t('financialUi.materials.allClasses'),studentName:search.value||t('financialUi.materials.allStudents'),status:status.value==='paid'?t('financialUi.materials.fullPayment'):status.value==='partial'?t('financialUi.materials.partial'):status.value==='unpaid'?t('financialUi.materials.unpaid'):t('financialUi.materials.allStatuses')}))
const items=ref<any[]>([]),sales=ref<any[]>([]),students=ref<any[]>([]),classes=ref<any[]>([]),history=ref<any[]>([])
const loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),itemOpen=ref(false),saleOpen=ref(false),payOpen=ref(false),historyOpen=ref(false),editId=ref(''),chosen=ref<any>(null)
const month=ref(''),classId=ref(''),search=ref(''),status=ref(''),ready=ref(false)
const form=reactive({title:'',owner_name:'',description:'',class_id:'',price:0,stock:0,cost:0,cost_on:todayKarachi(),active:true})
const sale=reactive({item:'',student:'',class_id:'',price:0,paid:0,date:todayKarachi(),request:''})
const payment=reactive({amount:0,date:todayKarachi(),request:'',complete:false})
const filtered=computed(()=>sales.value.filter(r=>(!month.value||r.sold_on.startsWith(month.value))&&(!classId.value||r.class_id===classId.value)&&(!status.value||r.payment_status===status.value)&&(!search.value||`${r.student_name} ${r.student_code||''}`.toLowerCase().includes(search.value.toLowerCase()))))
const total=(key:string)=>filtered.value.reduce((a,r)=>a+Number(r[key]||0),0)
const studentCount=(paid:boolean)=>new Set(filtered.value.filter(r=>r.student_id&&(r.payment_status==='paid')===paid).map(r=>r.student_id)).size
const available=(r:any)=>Number(book?r.opening_stock:r.produced_quantity)-sales.value.filter(s=>s[`${props.kind}_id`]===r.id).reduce((a,s)=>a+Number(s.quantity),0)
async function load(){if(!db)return;loading.value=true;ready.value=false;error.value='';try{
 const result=await Promise.all([allRows(()=>db.from(`${props.kind}s`).select('*').order('id')),allRows(()=>db.from(`${props.kind}_sale_overview`).select('*').order('id')),allRows(()=>db.from('students').select('id,student_code,first_name,last_name').order('id')),allRows(()=>db.from('class_rooms').select('id,title').order('id'))]);
 [items.value,sales.value,students.value,classes.value]=result;ready.value=true
}catch(e){error.value=errText(e)}finally{loading.value=false}}
function edit(r?:any){editId.value=r?.id||'';Object.assign(form,{title:r?.title||'',owner_name:r?.owner_name||'',description:r?.description||'',class_id:r?.class_id||'',price:Number((book?r?.sale_price:r?.default_sale_price)||0),stock:Number((book?r?.opening_stock:r?.produced_quantity)||0),cost:Number(r?.total_print_cost||0),cost_on:r?.printing_cost_on||todayKarachi(),active:r?.active??true});itemOpen.value=true}
async function saveItem(){if(!db||saving.value)return;saving.value=true;error.value='';try{
 const payload: Record<string,string|number|boolean|null>=book?{title:form.title.trim(),owner_name:form.owner_name.trim(),description:form.description||null,sale_price:form.price,opening_stock:form.stock,active:form.active}:{title:form.title.trim(),class_id:form.class_id,default_sale_price:form.price,produced_quantity:form.stock,total_print_cost:form.cost,printing_cost_on:form.cost_on,active:form.active};
 if(!payload.title||(book&&!form.owner_name.trim()))throw Error(t('financialUi.materials.requiredFields'));
 const q=editId.value?await db.from(`${props.kind}s`).update(payload).eq('id',editId.value):await db.from(`${props.kind}s`).insert(payload);if(q.error)throw q.error;
 itemOpen.value=false;success.value=t('financialUi.materials.saved');await load()
}catch(e){error.value=errText(e)}finally{saving.value=false}}
function newSale(){Object.assign(sale,{item:'',student:'',class_id:'',price:0,paid:0,date:todayKarachi(),request:crypto.randomUUID()});saleOpen.value=true}
function selectItem(){const r=items.value.find(i=>i.id===sale.item);if(r){sale.price=Number(book?r.sale_price:r.default_sale_price);if(!book)sale.class_id=r.class_id||''}}
async function sell(){if(!db||saving.value)return;saving.value=true;error.value='';try{const q=await db.rpc('sell_material',{p_kind:props.kind,p_item:sale.item,p_student:sale.student,p_class:sale.class_id,p_price:sale.price,p_paid:sale.paid,p_date:sale.date,p_request:sale.request});if(q.error)throw q.error;saleOpen.value=false;success.value=t('financialUi.materials.saleSaved');await load()}catch(e){error.value=errText(e)}finally{saving.value=false}}
function openPay(r:any,complete=false){chosen.value=r;Object.assign(payment,{amount:Number(r.balance_due),date:todayKarachi(),request:crypto.randomUUID(),complete});payOpen.value=true}
async function pay(){if(!db||saving.value)return;saving.value=true;error.value='';try{const q=await db.rpc('pay_material',{p_kind:props.kind,p_sale:chosen.value.id,p_amount:payment.amount,p_date:payment.date,p_request:payment.request,p_complete:payment.complete});if(q.error)throw q.error;payOpen.value=false;success.value=t('financialUi.materials.paymentSaved');await load()}catch(e){error.value=errText(e)}finally{saving.value=false}}
async function showHistory(r:any){if(!db)return;chosen.value=r;error.value='';try{history.value=await allRows(()=>db.from('material_payments').select('*').eq(`${props.kind}_sale_id`,r.id).order('created_at').order('id'));historyOpen.value=true}catch(e){error.value=errText(e)}}
async function voidPayment(r:any){if(!db||saving.value)return;const reason=window.prompt(t('financialUi.materials.voidPaymentPrompt'));if(!reason)return;saving.value=true;try{const q=await db.rpc('void_material_payment',{p_id:r.id,p_reason:reason});if(q.error)throw q.error;await showHistory(chosen.value);await load();success.value=t('financialUi.materials.paymentVoided')}catch(e){error.value=errText(e)}finally{saving.value=false}}
function print(){window.print()}
onMounted(load)
</script>
<template><div>
<div class="no-print"><PageTitle :title="title" :subtitle="book?t('financialUi.materials.titleBookFunds'):t('financialUi.materials.titleChapterFunds')"><button class="btn" :disabled="loading" @click="load">{{ t('financialUi.refresh') }}</button><button class="btn primary" @click="edit()"><Plus :size="16"/> {{ t('financialUi.materials.new') }}</button><button class="btn" :disabled="!ready" @click="newSale">{{ t('financialUi.materials.sale') }}</button><button class="btn" :disabled="!ready||loading" @click="print"><Printer :size="16"/> {{ t('financialUi.materials.printReport') }}</button></PageTitle>
<Notice :message="error" kind="error"/><Notice :message="success" kind="success"/>
<section class="card"><div class="card-header"><h3>{{ t('financialUi.materials.inventory',{title}) }}</h3><BookOpen :size="20"/></div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t('financialUi.materials.name') }} / {{ t('financialUi.identifier') }}</th><th>{{book?t('financialUi.materials.owner'):t('financialUi.class')}}</th><th>{{ t('financialUi.materials.price') }}</th><th>{{ t('financialUi.materials.stock') }}</th><th v-if="!book">{{ t('financialUi.materials.printingCost') }}</th><th>{{ t('financialUi.materials.registeredOn') }}</th><th>{{ t('financialUi.status') }}</th><th>{{ t('financialUi.partners.edit') }}</th></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td>{{r.title}}<small class="muted material-id">{{r.id}}</small></td><td>{{book?r.owner_name:classes.find(c=>c.id===r.class_id)?.title||'—'}}</td><td>{{money(book?r.sale_price:r.default_sale_price)}}</td><td>{{available(r)}}</td><td v-if="!book">{{money(r.total_print_cost)}}</td><td>{{r.created_at?.slice(0,10)}}</td><td>{{r.active?t('financialUi.materials.active'):t('financialUi.materials.inactive')}}</td><td><button class="btn small-btn" @click="edit(r)"><Pencil :size="14"/></button></td></tr></tbody></table></div></section>
<div class="table-toolbar"><label>{{ t('financialUi.materials.monthSales') }}<input v-model="month" type="month"/></label><label>{{ t('financialUi.class') }}<select v-model="classId"><option value="">{{ t('financialUi.all') }}</option><option v-for="c in classes" :key="c.id" :value="c.id">{{c.title}}</option></select></label><label>{{ t('financialUi.materials.studentSearch') }}<input v-model="search"/></label><label>{{ t('financialUi.status') }}<select v-model="status"><option value="">{{ t('financialUi.all') }}</option><option value="paid">{{ t('financialUi.materials.received') }}</option><option value="partial">{{ t('financialUi.materials.partial') }}</option><option value="unpaid">{{ t('financialUi.materials.unpaid') }}</option></select></label></div></div>
<PrintReport :title="t('financialUi.materials.reportTitle',{title})" :subtitle="reportSubtitle">
<p>{{book?t('financialUi.materials.accountBook'):t('financialUi.materials.chapterRevenue')}} {{ t('financialUi.materials.selectedSalesPayment') }}</p>
<div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t('financialUi.materials.studentSearch') }}</th><th>{{ t('financialUi.class') }}</th><th>{{book?t('financialUi.materials.books'):t('financialUi.materials.chapters')}}</th><th>{{ t('financialUi.materials.saleDate') }}</th><th>{{ t('financialUi.materials.lastPayment') }}</th><th>{{ t('financialUi.materials.totalPrice') }}</th><th>{{ t('financialUi.monthlyReport.received') }}</th><th>{{ t('financialUi.materials.remaining') }}</th><th>{{ t('financialUi.status') }}</th><th class="no-print">{{ t('financialUi.actions') }}</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td>{{r.student_name||t('financialUi.materials.oldSale')}}<small class="material-id">{{r.student_code}}</small></td><td>{{r.class_name||'—'}}</td><td>{{r.title}} ({{r.quantity}})</td><td>{{r.sold_on}}</td><td>{{r.last_paid_on||'—'}}</td><td>{{money(r.total_price)}}</td><td>{{money(r.paid_total)}}</td><td>{{money(r.balance_due)}}</td><td><label class="paid-label"><input v-if="book" type="checkbox" :checked="r.payment_status==='paid'" :disabled="saving||r.payment_status==='paid'" :aria-label="t('financialUi.materials.recordFullPayment')" @click.prevent="openPay(r,true)"/><span :class="['badge',r.payment_status==='paid'?'success':'warning']">{{r.payment_status==='paid'?'✓ '+t('financialUi.materials.received'):t('financialUi.materials.remaining')}}</span></label></td><td class="no-print"><button class="btn small-btn" :disabled="r.balance_due<=0||saving" @click="openPay(r)">{{ t('financialUi.payment') }}</button> <button class="btn small-btn" @click="showHistory(r)">{{ t('financialUi.history') }}</button></td></tr></tbody><tfoot><tr><th colspan="5">{{ t('financialUi.total') }}</th><th>{{money(total('total_price'))}}</th><th>{{money(total('paid_total'))}}</th><th>{{money(total('balance_due'))}}</th><th></th><th class="no-print"></th></tr></tfoot></table></div>
<p v-if="book">{{ t('financialUi.materials.fullPayingStudents',{paid:studentCount(true)}) }} · {{ t('financialUi.materials.studentsWithBalance',{unpaid:studentCount(false)}) }}</p><p v-if="loading">{{ t('financialUi.loading') }}</p><p v-else-if="!filtered.length">{{ t('financialUi.materials.noSales') }}</p>
</PrintReport>
<ModalBox :open="itemOpen" :title="editId?t('financialUi.materials.editInfo'):t('financialUi.materials.new')" @close="itemOpen=false"><Notice :message="error" kind="error"/><form @submit.prevent="saveItem"><div class="form-grid"><label>{{ t('financialUi.materials.name') }}<input v-model="form.title" required/></label><label v-if="book">{{ t('financialUi.materials.owner') }}<input v-model="form.owner_name" required/></label><label v-else>{{ t('financialUi.class') }}<select v-model="form.class_id" required><option value="">{{ t('financialUi.materials.chooseClass') }}</option><option v-for="c in classes" :key="c.id" :value="c.id">{{c.title}}</option></select></label><label>{{ t('financialUi.materials.salePrice') }}<input v-model.number="form.price" type="number" min="0" step="0.01" required/></label><label>{{ t('financialUi.materials.totalCopies') }}<input v-model.number="form.stock" type="number" min="0" step="1" required/></label><template v-if="!book"><label>{{ t('financialUi.materials.totalPrintingCost') }}<input v-model.number="form.cost" type="number" min="0" step="0.01" required/></label><label>{{ t('financialUi.materials.printingDate') }}<input v-model="form.cost_on" type="date" required/></label><p class="wide hint">{{ t('financialUi.materials.printingExpenseNote') }}</p></template><label v-if="book" class="wide">{{ t('financialUi.materials.details') }}<textarea v-model="form.description"/></label><label>{{ t('financialUi.status') }}<select v-model="form.active"><option :value="true">{{ t('financialUi.materials.active') }}</option><option :value="false">{{ t('financialUi.materials.inactive') }}</option></select></label></div><div class="form-footer"><button class="btn primary" :disabled="saving">{{ t('financialUi.save') }}</button></div></form></ModalBox>
<ModalBox :open="saleOpen" :title="t('financialUi.materials.saleAndPayment')" @close="saleOpen=false"><Notice :message="error" kind="error"/><form @submit.prevent="sell"><div class="form-grid"><label>{{ t('financialUi.student') }}<select v-model="sale.student" required><option value="">{{ t('financialUi.materials.chooseStudent') }}</option><option v-for="s in students" :key="s.id" :value="s.id">{{s.first_name}} {{s.last_name}} · {{s.student_code}}</option></select></label><label>{{title}}<select v-model="sale.item" required @change="selectItem"><option value="">{{ t('financialUi.select') }}</option><option v-for="i in items.filter(i=>i.active&&available(i)>0)" :key="i.id" :value="i.id">{{i.title}}</option></select></label><label>{{ t('financialUi.class') }}<select v-model="sale.class_id" required :disabled="!book"><option value="">{{ t('financialUi.materials.chooseClass') }}</option><option v-for="c in classes" :key="c.id" :value="c.id">{{c.title}}</option></select></label><label>{{ t('financialUi.materials.price') }}<input v-model.number="sale.price" type="number" min="0" step="0.01" required/></label><label>{{ t('financialUi.monthlyReport.received') }}<input v-model.number="sale.paid" type="number" min="0" :max="sale.price" step="0.01" required/></label><label>{{ t('financialUi.materials.salePaymentDate') }}<input v-model="sale.date" type="date" required/></label></div><p>{{ t('financialUi.materials.remaining') }}: {{money(sale.price-sale.paid)}}</p><div class="form-footer"><button class="btn primary" :disabled="saving">{{ t('financialUi.materials.confirmSale') }}</button></div></form></ModalBox>
<ModalBox :open="payOpen" :title="t('financialUi.materials.recordPayment')" @close="payOpen=false"><Notice :message="error" kind="error"/><form @submit.prevent="pay"><p>{{chosen?.student_name}} · {{chosen?.title}}</p><label>{{ t('financialUi.amount') }}<input v-model.number="payment.amount" type="number" min="0.01" :max="chosen?.balance_due" step="0.01" :disabled="payment.complete" required/></label><label>{{ t('financialUi.materials.actualPaymentDate') }}<input v-model="payment.date" type="date" required/></label><p v-if="payment.complete">{{ t('financialUi.materials.payFullBalance') }}</p><div class="form-footer"><button class="btn primary" :disabled="saving">{{ t('financialUi.materials.confirmPayment') }}</button></div></form></ModalBox>
<ModalBox :open="historyOpen" :title="t('financialUi.materials.paymentsHistory')" @close="historyOpen=false"><Notice :message="error" kind="error"/><p v-if="!history.length">{{ t('financialUi.materials.noPayments') }}</p><div v-for="r in history" :key="r.id" class="quick-item"><div>{{money(r.amount)}} · {{r.paid_on}}<p v-if="r.voided_at">{{ t('financialUi.materials.voidedReason',{reason:r.void_reason}) }}</p></div><button v-if="!r.voided_at" class="btn danger small-btn" :disabled="saving" @click="voidPayment(r)">{{ t('financialUi.voidWithReason') }}</button></div></ModalBox>
</div></template>
